    Bug 2037408 - Use preference to suppress signing warning, instead of overriding window.isCorrectlySigned. r=aleca


    After bug 2032014, all installed add-ons in the Add-on Manager show a "could not be verifed"
    warning, because we do not sign add-ons. Instead of finding an alternative approach to override
    the `isCorrectlySigned` method, this patch supresses the warning via the dedicated preference
    `extensions.ui.disableUnsignedWarnings`.

    Differential Revision: https://phabricator.services.mozilla.com/D298806

diff --git a/mail/app/profile/all-thunderbird.js b/mail/app/profile/all-thunderbird.js
index 5d7b3c164ca..b96f2e7532e 100644
--- a/mail/app/profile/all-thunderbird.js
+++ b/mail/app/profile/all-thunderbird.js
@@ -232,6 +232,10 @@ pref("extensions.startupScanScopes", 4);
 pref("extensions.update.requireBuiltInCerts", false);
 pref("extensions.install.requireBuiltInCerts", false);

+// Allow experiments and suppress unsigned warnings.
+pref("extensions.experiments.enabled", true);
+pref("extensions.ui.disableUnsignedWarnings", true);
+
 // Allow Experiments to be suppressed.
 pref("extensions.experiments.suppressed", false);
 // Comma-separated list of add-on IDs exempt from experiment suppression.
